foundation_consolidation.starter_code:
def tally(lst):
    # 补全功法：返回 [大于0的个数, 元素之和]
    pass

foundation_consolidation.solution:
def tally(lst):
    count = 0
    total = 0
    for x in lst:
        total += x
        if x > 0:
            count += 1
    return [count, total]
